CREATE TABLE "workspaces" ("id" text PRIMARY KEY NOT NULL, "name" text NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "accounts" ("id" text PRIMARY KEY NOT NULL, "workspace_id" text NOT NULL REFERENCES "workspaces"("id"), "name" text NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "commercial_documents" ("id" text PRIMARY KEY NOT NULL, "account_id" text NOT NULL REFERENCES "accounts"("id"), "kind" text NOT NULL, "effective_from" text NOT NULL, "terms" jsonb NOT NULL, "evidence" jsonb NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "crm_states" ("account_id" text PRIMARY KEY NOT NULL REFERENCES "accounts"("id"), "terms" jsonb NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "billing_states" ("account_id" text PRIMARY KEY NOT NULL REFERENCES "accounts"("id"), "terms" jsonb NOT NULL, "version" text DEFAULT '1' NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "cases" ("id" text PRIMARY KEY NOT NULL, "workspace_id" text NOT NULL REFERENCES "workspaces"("id"), "account_id" text NOT NULL REFERENCES "accounts"("id"), "title" text NOT NULL, "status" text NOT NULL, "financial_impact_cents" text NOT NULL, "trueforge_session_id" text, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE "case_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "case_id" text NOT NULL REFERENCES "cases"("id"), "sequence" text NOT NULL, "type" text NOT NULL, "actor" text NOT NULL, "payload" jsonb NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "case_events_case_sequence" ON "case_events" USING btree ("case_id","sequence");
CREATE TABLE "proposals" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "case_id" text NOT NULL REFERENCES "cases"("id"), "before" jsonb NOT NULL, "after" jsonb NOT NULL, "impact_cents" text NOT NULL, "idempotency_key" text NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "proposals_idempotency" ON "proposals" USING btree ("idempotency_key");
CREATE TABLE "approvals" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "proposal_id" uuid NOT NULL REFERENCES "proposals"("id"), "case_id" text NOT NULL REFERENCES "cases"("id"), "trueforge_approval_id" text NOT NULL, "decision" text DEFAULT 'pending' NOT NULL, "decided_by" text, "expires_at" timestamp with time zone NOT NULL, "consumed_at" timestamp with time zone, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "approvals_trueforge_id" ON "approvals" USING btree ("trueforge_approval_id");
CREATE TABLE "verification_outcomes" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "case_id" text NOT NULL REFERENCES "cases"("id"), "passed" text NOT NULL, "observed" jsonb NOT NULL, "expected" jsonb NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
